#define DIRECT_J_NO_MAIN
#include "ibp.hpp"
int main(int argc,char**argv){try{json cfg;{std::ifstream f(argv[1]);f>>cfg;}prime=cfg.at("prime");nmod_init(&mod,prime);auto xs=cfg.at("xs").get<std::vector<U>>();int train=cfg.at("train");std::vector<std::string>targets=cfg.at("targets").get<std::vector<std::string>>(),basis=cfg.at("basis").get<std::vector<std::string>>();std::map<std::pair<int,int>,std::vector<U>>values;std::map<std::string,int>cols;for(int j=0;j<int(basis.size());++j)cols[basis[j]]=j;
int count=0;for(auto&path:cfg.at("files")){json point;{std::ifstream f(path.get<std::string>());f>>point;}if(point.at("basis")!=cfg.at("basis"))throw std::runtime_error("basis mismatch");for(int i=0;i<int(targets.size());++i){auto&row=point.at("reductions").at(targets[i]);for(auto it=row.begin();it!=row.end();++it){auto key=std::make_pair(i,cols.at(it.key()));auto&v=values[key];if(v.empty())v.resize(xs.size());v[count]=it.value().get<U>();}}++count;}
std::vector<U>fitxs(xs.begin(),xs.begin()+train);Interpolator interp(fitxs);json entries=json::array();int worstsum=-1,worstnum=0,worstden=0;bool pass=true;int fitted=0;
for(auto&[slot,y]:values){std::vector<U>fit(y.begin(),y.begin()+train);Fraction rat;if(!interp.reconstruct(fit,fitxs,rat)){pass=false;break;}for(size_t k=train;k<xs.size();++k){U d=nmod_poly_evaluate_nmod(rat.d.v,xs[k]);if(!d||nmod_poly_evaluate_nmod(rat.n.v,xs[k])!=mul(y[k],d)){pass=false;break;}}if(!pass)break;
int dn=rat.n.zero()?-1:rat.n.deg(),dd=rat.d.deg();if(dn+dd>worstsum){worstsum=dn+dd;worstnum=dn;worstden=dd;}if(!rat.n.zero())entries.push_back({slot.first,slot.second,json::array({polyjson(rat.n),polyjson(rat.d)})});++fitted;}
json out={{"passed",pass},{"train",train},{"holdouts",xs.size()-train},{"nonzero_slots",values.size()},{"slots_fitted",fitted},{"max_degree_sum",worstsum},{"worst_numerator_degree",worstnum},{"worst_denominator_degree",worstden}};if(pass)out["matrix"]={{"shape",{targets.size(),basis.size()}},{"entries",entries}};std::ofstream f(argv[2]);f<<out.dump()<<'\n';std::cout<<"train="<<train<<" pass="<<pass<<" slots="<<fitted<<" maxsum="<<worstsum<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
